import React, { useState, useEffect } from 'react';
import { useBrowserHijacking } from '../hooks/useBrowserHijacking';

interface FullscreenOverlayProps {
  onEscape: () => void;
  onLearnMore: () => void;
}

const FullscreenOverlay: React.FC<FullscreenOverlayProps> = ({ onEscape, onLearnMore }) => {
  const [showOverlay, setShowOverlay] = useState(false);
  const [showEscapeButton, setShowEscapeButton] = useState(false);

  // Use real scareware browser hijacking techniques
  const { blockedAttempts, isFullscreen } = useBrowserHijacking({
    forceFullscreen: true,
    preventEscape: true,
    preventTabSwitch: true,
    preventMouseEvents: true,
    preventWindowControl: true
  });

  useEffect(() => {
    // Show overlay after a short delay
    const timer1 = setTimeout(() => setShowOverlay(true), 500);
    
    // Show escape button after 5 seconds
    const timer2 = setTimeout(() => setShowEscapeButton(true), 5000);

    return () => {
      clearTimeout(timer1);
      clearTimeout(timer2);
    };
  }, []);

  const handleEscape = () => {
    setShowOverlay(false);
    onEscape();
  };

  const handleLearnMore = () => {
    setShowOverlay(false);
    onLearnMore();
  };

  if (!showOverlay) {
    return null;
  }

  return (
    <>
      {/* Real scareware technique: Multiple overlay layers */}
      <div 
        className="fullscreen-overlay"
        style={{
          background: 'linear-gradient(45deg, #ff0000, #ff6b6b, #ff0000)',
          animation: 'flash 0.5s infinite alternate'
        }}
      >
        <div style={{ textAlign: 'center', maxWidth: '600px' }}>
          <div style={{ fontSize: '4rem', marginBottom: '2rem' }}>🚨</div>
          <h1 style={{ marginBottom: '2rem', fontSize: '3rem', textShadow: '2px 2px 4px rgba(0,0,0,0.8)' }}>
            SYSTEM LOCKED!
          </h1>
          <div style={{ fontSize: '1.5rem', marginBottom: '2rem' }}>
            Your computer has been compromised by multiple viruses!
          </div>
          <div style={{ fontSize: '1.2rem', marginBottom: '2rem' }}>
            All your personal data is being stolen!
            <br />
            Banking information compromised!
            <br />
            Passwords have been leaked!
          </div>
          <div style={{ 
            background: 'rgba(255, 255, 255, 0.1)', 
            padding: '1rem', 
            borderRadius: '8px',
            marginBottom: '2rem',
            border: '2px solid #fff'
          }}>
            <div style={{ fontSize: '1.1rem', marginBottom: '1rem' }}>
              <strong>IMMEDIATE ACTION REQUIRED:</strong>
            </div>
            <div style={{ fontSize: '1rem' }}>
              Call our support team NOW: 1-800-FAKE-SUPPORT
              <br />
              Or purchase our security suite for $99.99
            </div>
          </div>
          
          <div style={{ 
            background: 'rgba(255, 255, 255, 0.2)', 
            padding: '1rem', 
            borderRadius: '8px',
            marginBottom: '2rem',
            fontSize: '0.9rem'
          }}>
            <strong>SIMULATION MODE:</strong> This is a safe educational demonstration.
            <br />
            Real browser hijacking would be much more difficult to escape.
            <br />
            <strong>Blocked attempts to escape: {blockedAttempts}</strong>
          </div>

          {showEscapeButton && (
            <div style={{ marginTop: '2rem' }}>
              <button 
                className="button button-success" 
                onClick={handleEscape}
                style={{ 
                  fontSize: '1.2rem', 
                  padding: '1rem 2rem', 
                  marginRight: '1rem',
                  background: '#28a745',
                  border: '3px solid #fff',
                  boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
                }}
              >
                🚪 Emergency Escape (Simulation)
              </button>
              <button 
                className="button button-primary" 
                onClick={handleLearnMore}
                style={{ 
                  fontSize: '1.2rem', 
                  padding: '1rem 2rem',
                  background: '#007bff',
                  border: '3px solid #fff',
                  boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
                }}
              >
                📚 Learn More
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Real scareware technique: Persistent popup that reappears */}
      <div 
        style={{
          position: 'fixed',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          background: 'white',
          border: '3px solid #ff0000',
          borderRadius: '8px',
          padding: '1rem',
          zIndex: 10001,
          boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
          animation: 'shake 0.5s infinite'
        }}
      >
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>⚠️</div>
          <div style={{ fontWeight: 'bold', color: '#ff0000', marginBottom: '0.5rem' }}>
            URGENT: System Compromised!
          </div>
          <div style={{ fontSize: '0.9rem', marginBottom: '1rem' }}>
            Your computer is infected with 47 viruses!
            <br />
            <strong>SIMULATION MODE</strong>
          </div>
          <button 
            onClick={handleEscape}
            style={{
              background: '#ff0000',
              color: 'white',
              border: 'none',
              padding: '0.5rem 1rem',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Remove Threats Now
          </button>
        </div>
      </div>
    </>
  );
};

export default FullscreenOverlay;
